import collections

def process_data(data):
    output_list = sorted(data, key=lambda item: item['grade'], reverse=True)

    freq_map = collections.Counter(item['grade'] for item in data)

    t_count = 0
    for v in freq_map.values():
        if v > 1:
            t_count += 1

    result_stats = {'tied_grades': t_count}
    return output_list, result_stats
